class HASLTestCard extends HTMLElement {
  connectedCallback() {
    const ua = navigator.userAgent;

    this.innerHTML = `
      <pre style="
        white-space: pre-wrap;
        font-size: 18px;
        padding: 20px;
        color: white;
        background: black;
      ">${ua}

Chrome:
${ua.match(/Chrome\/([\d.]+)/)?.[1] ?? "unknown"}

customElements:
${"customElements" in window}

Shadow DOM:
${"attachShadow" in Element.prototype}

Promise:
${"Promise" in window}

Map:
${"Map" in window}

Set:
${"Set" in window}

Symbol:
${"Symbol" in window}

ES modules:
${"noModule" in HTMLScriptElement.prototype}
</pre>
    `;
  }
}


declare global {
    interface Window {
        customCards: Array<Object>
    }
}
customElements.define('hasl4-departure-card', HASLTestCard)

window.customCards = window.customCards || []
window.customCards.push({
    type: "hasl4-departure-card",
    name: "HASL4 Departure card",
    description: "Show departure times for SL Trafik",
})
